import torch
import numpy as np
from transformers import AutoTokenizer
from typing import Union, List
from tqdm import tqdm

CAP_PAD_SIZE = 64


class LATENT_SIZE:
    value = 128


def create_coordinate_grid(size, start=None, device=None):
    if start is None:
        start = (0 for _ in size)

    axes = [torch.arange(x0, x0 + span, dtype=torch.int32, device=device) for x0, span in zip(start, size)]
    grids = torch.meshgrid(axes, indexing="ij")
    return torch.stack(grids, dim=-1)


def genearte_rope():
    theta = 256.0
    axis_dims = [32, 48, 48]
    axes_lens = [1024, 512, 512]

    freqs_cis = []
    for i, (d, e) in enumerate(zip(axis_dims, axes_lens)):
        freqs = 1.0 / (theta ** (torch.arange(0, d, 2, dtype=torch.float64) / d))
        timestep = torch.arange(e, dtype=torch.float64)
        freqs = torch.outer(timestep, freqs).float()
        freqs_cis_i = torch.polar(torch.ones_like(freqs), freqs).to(torch.complex64)
        freqs_cis.append(freqs_cis_i)

    noise, text = [], []
    noise_ids = create_coordinate_grid((1, LATENT_SIZE.value // 2, LATENT_SIZE.value //
                                        2), (65, 0, 0), device="cpu").flatten(0, 2)
    text_ids = create_coordinate_grid((64, 1, 1), (1, 0, 0), device="cpu").flatten(0, 2)
    for i in range(len(axis_dims)):
        noise.append(freqs_cis[i][noise_ids[:, i]])
        text.append(freqs_cis[i][text_ids[:, i]])
    noise, text = torch.cat(noise, dim=-1), torch.cat(text, dim=-1)
    return torch.view_as_real(noise), torch.view_as_real(text)


class EncoderWrapper:

    def __init__(self, backend, emb_backend):
        self.backend = backend
        self.emb_backend = emb_backend

    def __call__(self, input_ids,
                 attention_mask,
                 output_hidden_states):
        input_ids = input_ids.reshape(1, -1)
        device = input_ids.device
        dtype = torch.float16
        embedding = self.emb_backend.forward(input_ids, tensor_type='pt')[0].to(dtype).to(device)
        seqlen = input_ids.shape[1]
        attention_mask = torch.ones([1, 1, seqlen, seqlen], device=device, dtype=dtype)
        attention_mask = attention_mask.tril()
        attention_mask = (1-attention_mask) * -40
        position_ids = torch.arange(seqlen, device=device, dtype=dtype).reshape(1, -1)
        res = self.backend.forward([embedding,
                                    attention_mask,
                                    position_ids], tensor_type='pt')[0].to(dtype).to(device)
        return res


